import type {
  BackendContractManifest,
  EndpointContract,
  TypeDeclaration,
  TypeProperty,
  TypeShape,
} from "./types";

const GENERATED_HEADER =
  "// This file is generated by backend-contract-inspector. Do not edit it manually.\n";

const primitiveTypeMap: Record<string, string> = {
  string: "string",
  number: "number",
  boolean: "boolean",
  bigint: "bigint",
  symbol: "symbol",
  object: "Record<string, unknown>",
  any: "unknown",
  unknown: "unknown",
  undefined: "undefined",
  void: "void",
};

function isSafePropertyName(name: string): boolean {
  return /^[A-Za-z_$][\w$]*$/.test(name);
}

function renderPropertyName(name: string): string {
  return isSafePropertyName(name) ? name : JSON.stringify(name);
}

function uniqueStrings(values: string[]): string[] {
  return [...new Set(values)];
}

function shapeReferences(shape: TypeShape | undefined): string[] {
  if (!shape) return [];
  switch (shape.kind) {
    case "reference":
      return [shape.name ?? "", ...(shape.args?.flatMap(shapeReferences) ?? [])].filter(Boolean);
    case "array":
      return shapeReferences(shape.element);
    case "tuple":
      return shape.elements?.flatMap(shapeReferences) ?? [];
    case "object":
      return shape.properties?.flatMap((property) => shapeReferences(property.type)) ?? [];
    case "union":
    case "intersection":
      return shape.variants?.flatMap(shapeReferences) ?? [];
    default:
      return [];
  }
}

function reachableDeclarations(manifest: BackendContractManifest): TypeDeclaration[] {
  const declarationsByName = new Map(manifest.declarations.map((declaration) => [declaration.name, declaration]));
  const included = new Set<string>();
  const queue: string[] = [];

  const enqueueShape = (shape: TypeShape | undefined) => {
    for (const name of shapeReferences(shape)) {
      if (!included.has(name) && declarationsByName.has(name)) queue.push(name);
    }
  };

  for (const endpoint of manifest.endpoints) {
    enqueueShape(endpoint.response.type);
    for (const parameter of endpoint.request.parameters) enqueueShape(parameter.type);
  }

  while (queue.length) {
    const name = queue.shift();
    if (!name || included.has(name)) continue;
    const declaration = declarationsByName.get(name);
    if (!declaration) continue;
    included.add(name);
    if (declaration.alias) enqueueShape(declaration.alias);
    for (const field of declaration.fields) enqueueShape(field.type);
    for (const base of declaration.extends ?? []) {
      if (!included.has(base) && declarationsByName.has(base)) queue.push(base);
    }
  }

  return [...included]
    .map((name) => declarationsByName.get(name))
    .filter((declaration): declaration is TypeDeclaration => declaration !== undefined)
    .sort((left, right) => left.name.localeCompare(right.name));
}

function flattenFields(
  declaration: TypeDeclaration,
  declarationsByName: Map<string, TypeDeclaration>,
  seen = new Set<string>(),
): TypeProperty[] {
  if (seen.has(declaration.name)) return [];
  const nextSeen = new Set(seen).add(declaration.name);
  const inherited = (declaration.extends ?? []).flatMap((baseName) => {
    const base = declarationsByName.get(baseName);
    return base ? flattenFields(base, declarationsByName, nextSeen) : [];
  });
  const fields = [...inherited, ...declaration.fields];
  const byName = new Map(fields.map((field) => [field.name, field]));
  return [...byName.values()];
}

function renderShape(
  shape: TypeShape | undefined,
  declarationsByName: Map<string, TypeDeclaration>,
  options: { qualify: boolean; genericNames: Set<string> },
): string {
  if (!shape) return "unknown";

  switch (shape.kind) {
    case "unknown":
      return "unknown";
    case "binary":
      return "Blob";
    case "primitive":
      return primitiveTypeMap[shape.name ?? ""] ?? "unknown";
    case "literal":
      if (shape.value === null) return "null";
      return typeof shape.value === "string" ? JSON.stringify(shape.value) : String(shape.value);
    case "reference": {
      const name = shape.name ?? "unknown";
      if (options.genericNames.has(name)) return name;
      if (name === "Date") return "string";
      if (name === "Buffer" || name === "StreamableFile") return "Blob";
      if (name === "Array") {
        return `Array<${renderShape(shape.args?.[0], declarationsByName, options)}>`;
      }
      if (name === "ReadonlyArray") {
        return `ReadonlyArray<${renderShape(shape.args?.[0], declarationsByName, options)}>`;
      }
      if (name === "Record") {
        return `Record<${renderShape(shape.args?.[0], declarationsByName, options)}, ${renderShape(shape.args?.[1], declarationsByName, options)}>`;
      }
      if (name === "Map") {
        return `Record<${renderShape(shape.args?.[0], declarationsByName, options)}, ${renderShape(shape.args?.[1], declarationsByName, options)}>`;
      }
      if (declarationsByName.has(name)) {
        const renderedName = options.qualify ? `BackendContract.${name}` : name;
        const args = shape.args?.length
          ? `<${shape.args.map((argument) => renderShape(argument, declarationsByName, options)).join(", ")}>`
          : "";
        return `${renderedName}${args}`;
      }
      return "unknown";
    }
    case "array":
      return `Array<${renderShape(shape.element, declarationsByName, options)}>`;
    case "tuple":
      return `[${(shape.elements ?? []).map((element) => renderShape(element, declarationsByName, options)).join(", ")}]`;
    case "object":
      return renderObjectShape(shape.properties ?? [], declarationsByName, options);
    case "union":
    case "intersection": {
      const variants = uniqueStrings(
        (shape.variants ?? []).map((variant) => renderShape(variant, declarationsByName, options)),
      );
      return variants.length ? variants.join(shape.kind === "intersection" ? " & " : " | ") : "unknown";
    }
  }
}

function renderObjectShape(
  properties: TypeProperty[],
  declarationsByName: Map<string, TypeDeclaration>,
  options: { qualify: boolean; genericNames: Set<string> },
): string {
  if (!properties.length) return "Record<string, unknown>";
  const fields = properties.map(
    (property) =>
      `${renderPropertyName(property.name)}${property.optional ? "?" : ""}: ${renderShape(property.type, declarationsByName, options)};`,
  );
  return `{ ${fields.join(" ")} }`;
}

function renderDeclaration(
  declaration: TypeDeclaration,
  declarationsByName: Map<string, TypeDeclaration>,
): string {
  const genericNames = new Set(declaration.typeParameters);
  const genericSuffix = declaration.typeParameters.length
    ? `<${declaration.typeParameters.join(", ")}>`
    : "";
  const options = { qualify: false, genericNames };

  if (declaration.kind === "enum") {
    const values = declaration.enumValues?.length
      ? declaration.enumValues.map((value) => (typeof value === "string" ? JSON.stringify(value) : String(value))).join(" | ")
      : "string";
    return `export type ${declaration.name} = ${values};`;
  }

  if (declaration.kind === "type") {
    return `export type ${declaration.name}${genericSuffix} = ${renderShape(declaration.alias, declarationsByName, options)};`;
  }

  const fields = flattenFields(declaration, declarationsByName);
  if (!fields.length) return `export type ${declaration.name}${genericSuffix} = Record<string, never>;`;
  const renderedFields = fields
    .map(
      (property) =>
        `  ${renderPropertyName(property.name)}${property.optional ? "?" : ""}: ${renderShape(property.type, declarationsByName, options)};`,
    )
    .join("\n");
  return `export interface ${declaration.name}${genericSuffix} {\n${renderedFields}\n}`;
}

function renderQueryType(
  endpoint: EndpointContract,
  declarationsByName: Map<string, TypeDeclaration>,
): string | undefined {
  const queryParameters = endpoint.request.parameters.filter((parameter) => parameter.location === "query");
  if (!queryParameters.length) return undefined;
  if (queryParameters.length === 1 && !queryParameters[0].field) {
    return renderQualifiedShape(queryParameters[0].type, declarationsByName);
  }
  const fields = queryParameters
    .map(
      (parameter) =>
        `${renderPropertyName(parameter.name)}?: ${renderQualifiedShape(parameter.type, declarationsByName)};`,
    )
    .join(" ");
  return `{ ${fields} }`;
}

function renderQualifiedShape(
  shape: TypeShape,
  declarationsByName: Map<string, TypeDeclaration>,
): string {
  return renderShape(shape, declarationsByName, { qualify: true, genericNames: new Set() });
}

function toMethodName(endpoint: EndpointContract, usedNames: Set<string>): string {
  const base = endpoint.handler.replace(/[^A-Za-z0-9_$]/g, "") || endpoint.method.toLowerCase();
  let name = /^[A-Za-z_$]/.test(base) ? base : `endpoint${base}`;
  if (usedNames.has(name)) name = `${name}${endpoint.controller.replace(/Controller$/, "")}`;
  let suffix = 2;
  while (usedNames.has(name)) name = `${base}${suffix++}`;
  usedNames.add(name);
  return name;
}

function endpointResponseType(
  endpoint: EndpointContract,
  declarationsByName: Map<string, TypeDeclaration>,
): string {
  return renderShape(endpoint.response.type, declarationsByName, {
    qualify: true,
    genericNames: new Set(),
  });
}

function querySerialization(): string {
  return `function toQueryString(query: Record<string, unknown> | undefined): string {
  if (!query) return "";
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    if (value === undefined || value === null || value === "") continue;
    if (Array.isArray(value)) {
      const values = value.filter((item) => item !== undefined && item !== null && item !== "");
      if (values.length) params.set(key, values.join(","));
      continue;
    }
    if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
      params.set(key, String(value));
    }
  }
  const serialized = params.toString();
  return serialized ? \`?\${serialized}\` : "";
}

function replacePathParameters(
  path: string,
  parameters: Record<string, string | number> | undefined,
): string {
  return path.replace(/:([A-Za-z_$][\\w$]*)/g, (_match, name: string) => {
    const value = parameters?.[name];
    if (value === undefined || value === null) {
      throw new Error(\`Falta el parámetro de ruta "\${name}".\`);
    }
    return encodeURIComponent(String(value));
  });
}`;
}

function parameterInterface(
  endpoint: EndpointContract,
  queryType: string | undefined,
  declarationsByName: Map<string, TypeDeclaration>,
): string | undefined {
  const pathParameters = endpoint.request.parameters.filter((parameter) => parameter.location === "path");
  const hasBody = endpoint.request.parameters.some((parameter) => parameter.location === "body");
  const hasFormData = endpoint.request.parameters.some((parameter) => parameter.location === "formData");
  if (!pathParameters.length && !queryType && !hasBody && !hasFormData) return undefined;

  const fields: string[] = [];
  if (pathParameters.length) {
    fields.push(
      `path: { ${pathParameters.map((parameter) => `${renderPropertyName(parameter.name)}: ${renderQualifiedShape(parameter.type, declarationsByName)}`).join("; ")} }`,
    );
  }
  if (queryType) fields.push(`query?: ${queryType}`);
  if (hasFormData) {
    fields.push("body: FormData");
  } else if (hasBody) {
    const body = endpoint.request.parameters.find((parameter) => parameter.location === "body");
    fields.push(`body: ${body ? renderQualifiedShape(body.type, declarationsByName) : "unknown"}`);
  }
  return `{ ${fields.join("; ")} }`;
}

function endpointFunction(
  endpoint: EndpointContract,
  methodName: string,
  declarationsByName: Map<string, TypeDeclaration>,
): string {
  const queryType = renderQueryType(endpoint, declarationsByName);
  const paramsType = parameterInterface(endpoint, queryType, declarationsByName);
  const pathParameters = endpoint.request.parameters.filter((parameter) => parameter.location === "path");
  const hasQuery = Boolean(queryType);
  const hasBody = endpoint.request.parameters.some((parameter) => parameter.location === "body" || parameter.location === "formData");
  const responseType = endpointResponseType(endpoint, declarationsByName);
  const pathExpression = pathParameters.length
    ? `replacePathParameters(${JSON.stringify(endpoint.clientPath)}, params.path)`
    : JSON.stringify(endpoint.clientPath);
  const queryExpression = hasQuery
    ? "toQueryString(params.query as unknown as Record<string, unknown>)"
    : '""';
  const argument = paramsType
    ? `params: ${paramsType}${pathParameters.length || hasBody ? "" : " = {}"}`
    : "";
  const bodyExpression = hasBody ? ",\n    body: params.body" : "";
  const responseExpression = endpoint.response.type.kind === "binary" ? ',\n    responseType: "blob"' : "";

  return `export function ${methodName}(${argument}): Promise<${responseType}> {
  const path = ${pathExpression};
  const query = ${queryExpression};
  return request<${responseType}>(\`\${path}\${query}\`, {
    method: ${JSON.stringify(endpoint.method)},
    auth: ${JSON.stringify(endpoint.auth === "public" ? "none" : "required")}${bodyExpression}${responseExpression}
  });
}`;
}

export function generateTypesSource(manifest: BackendContractManifest): string {
  const declarations = reachableDeclarations(manifest);
  const declarationsByName = new Map(declarations.map((declaration) => [declaration.name, declaration]));
  const chunks = [
    GENERATED_HEADER.trimEnd(),
    `export interface BackendProblemDetails {
  type: string;
  title: string;
  status: number;
  detail: string;
  code: string;
}`,
    ...declarations.map((declaration) => renderDeclaration(declaration, declarationsByName)),
  ];
  return `${chunks.join("\n\n")}\n`;
}

export function generateApiSource(manifest: BackendContractManifest): string {
  const usedNames = new Set<string>();
  const declarationsByName = new Map(
    manifest.declarations.map((declaration) => [declaration.name, declaration]),
  );
  const functions = manifest.endpoints.map((endpoint) => {
    const methodName = toMethodName(endpoint, usedNames);
    return endpointFunction(endpoint, methodName, declarationsByName);
  });

  return `${GENERATED_HEADER}
import { request } from "@/services/http/apiClient";
import type * as BackendContract from "./types";

${querySerialization()}

${functions.join("\n\n")}
`;
}

export function generateIndexSource(): string {
  return `${GENERATED_HEADER}export * from "./types";
export * from "./api";
`;
}

export function generateManifestSource(manifest: BackendContractManifest): string {
  return `${JSON.stringify(manifest, null, 2)}\n`;
}

export function generateContractFiles(manifest: BackendContractManifest): Record<string, string> {
  return {
    "manifest.json": generateManifestSource(manifest),
    "types.ts": generateTypesSource(manifest),
    "api.ts": generateApiSource(manifest),
    "index.ts": generateIndexSource(),
  };
}
